<template><PageShell title="Pacientes" subtitle="Dados administrativos e convênios"><div class="flex gap-3"><input v-model="search" class="input flex-1" placeholder="Buscar paciente"><button class="btn" @click="load">Buscar</button><button class="btn" @click="showForm=!showForm">Novo paciente</button></div><form v-if="showForm" class="panel grid gap-3 md:grid-cols-2" @submit.prevent="create"><input v-model="form.full_name" class="input" placeholder="Nome completo" required><input v-model="form.cpf" class="input" placeholder="CPF"><input v-model="form.birth_date" class="input" type="date"><input v-model="form.phone" class="input" placeholder="Telefone"><input v-model="form.email" class="input" type="email" placeholder="E-mail"><button class="btn">Cadastrar</button></form><div class="panel"><RouterLink v-for="p in patients" :key="p.id" :to="`/pacientes/${p.id}`" class="block border-b p-4 hover:bg-gray-50"><strong>{{ p.full_name }}</strong><span class="ml-4 text-gray-500">{{ p.phone }}</span></RouterLink></div></PageShell></template>
<script setup lang="ts">/* eslint-disable @typescript-eslint/no-explicit-any */import{onMounted,reactive,ref}from'vue';import api from '@/plugins/axios';import PageShell from '@/components/PageShell.vue';const patients=ref<any[]>([]),search=ref(''),showForm=ref(false),form=reactive({full_name:'',cpf:'',birth_date:'',phone:'',email:''});async function load(){patients.value=(await api.get('/patients',{params:{search:search.value}})).data}async function create(){await api.post('/patients',form);showForm.value=false;await load()}onMounted(load);</script>
